console.log(`Loaded ${FIXES.length} fixes so far (script may be extended with more before running).`);

async function main() {
  const { rows, col } = await getTabWithHeaders(TAB);
  const iSlug = col('story_slug');
  const iLang = col('lang');
  const iPara = col('paragraph_num');
  const iText = col('text');

  const requests = [];
  let matchedCount = 0;
  let mismatchCount = 0;

  for (const fix of FIXES) {
    // A handful of (slug, lang, paragraph_num) keys are duplicated in the
    // live tab (legacy/duplicate content rows), so match on the full old
    // text too and take the row whose live text matches verbatim.
    const candidates = rows
      .map((r, i) => ({ r, i }))
      .filter(
        ({ r }) => r[iSlug] === fix.slug && r[iLang] === fix.lang && String(r[iPara]) === String(fix.para)
      );
    if (candidates.length === 0) {
      console.error(`NOT FOUND: ${fix.slug} / ${fix.lang} / para ${fix.para}`);
      mismatchCount++;
      continue;
    }
    const exact = candidates.find(({ r }) => (r[iText] || '') === fix.old);
    if (!exact) {
      console.error(`MISMATCH (live cell(s) differ from expected "old" text): ${fix.slug} / ${fix.lang} / para ${fix.para}`);
      for (const { r } of candidates) console.error(`  live:     ${r[iText] || ''}`);
      console.error(`  expected: ${fix.old}`);
      mismatchCount++;
      continue;
    }
    const rowIdx = exact.i;
    const liveText = rows[rowIdx][iText] || '';

    matchedCount++;
    const sheetRow = rowIdx + 2; // +1 header, +1 to go from 0-index to 1-index
    console.log(`\n=== ${fix.slug} [${fix.lang}] paragraph ${fix.para} (row ${sheetRow}) ===`);
    console.log(`OLD: ${fix.old}`);
    console.log(`NEW: ${fix.new_}`);
    if (fix.note) console.log(`NOTE: ${fix.note}`);

    requests.push({
      range: `${TAB}!${colLetter(iText)}${sheetRow}`,
      values: [[fix.new_]],
    });
  }

  console.log(`\n\nSummary: ${matchedCount} matched and ready to write, ${mismatchCount} not found/mismatched.`);

  if (!WRITE) {
    console.log('\nDRY RUN — no changes written. Pass --write to apply.');
    return;
  }

  if (requests.length === 0) {
    console.log('Nothing to write.');
    return;
  }

  const sheets = await getSheetsClient();
  await sheets.spreadsheets.values.batchUpdate({
    spreadsheetId: SPREADSHEET_ID,
    requestBody: { valueInputOption: 'RAW', data: requests },
  });
  console.log(`Wrote ${requests.length} cells.`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
